.d-day-demo{position:relative;display:grid;place-items:center;font-family:Inter,system-ui,sans-serif}.d-day-demo-rail{position:relative;width:208px;height:36px;padding:0;border:1px solid #ffffff0f;border-radius:11px;background:#171717}.d-day-demo-indicator{position:absolute;left:5px;top:2px;width:64px;height:30px;border-radius:8px;background:#272727;box-shadow:inset 0 1px #ffffff0f,0 1px 2px #0000001f,0 8px 20px -8px #0000002e;transform:translateX(var(--d-day-position,66px));transition:none}
.d-day-demo[data-animating="true"] .d-day-demo-indicator{animation:d-day-demo-travel var(--dur-medium) var(--ease-bounce) both}
.d-day-demo-choice{position:absolute;left:4px;top:2px;width:66px;height:30px;padding:0;border:0;border-radius:8px;background:transparent;color:#6a6a6a;font:500 12.5px/18px Inter,system-ui,sans-serif;letter-spacing:-.0175px;cursor:pointer;transition:color var(--dur-fast) var(--ease-out)}.d-day-demo-choice:nth-of-type(2){left:70px}.d-day-demo-choice:nth-of-type(3){left:136px}.d-day-demo-choice img{position:absolute;left:10px;top:6px;display:block}.d-day-demo-choice:first-of-type img{left:12px}.d-day-demo-choice span{position:absolute;left:30px;top:5px}.d-day-demo-choice:first-of-type span{left:32px}.d-day-demo-choice[aria-checked="true"]{color:#f1f1f1}.d-day-demo-choice:focus-visible{outline:2px solid var(--focus-ring);outline-offset:1px}
.d-day-demo-status{position:absolute;left:50%;top:50%;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap;font-size:13px}.d-day-demo[data-initializing="true"] .d-day-demo-indicator{transition:none}
@keyframes d-day-demo-travel{from{transform:translateX(var(--d-day-from))}55%{transform:translateX(var(--d-day-peak))}80%,to{transform:translateX(var(--d-day-position))}}
@media(prefers-reduced-motion:reduce){.d-day-demo .d-day-demo-indicator{animation:none;transition:none}.d-day-demo-choice{transition:color var(--dur-quick) var(--ease-out)}}

.d-badge-demo{position:relative;display:grid;place-items:center;font-family:Inter,system-ui,sans-serif}.d-badge-demo-wrap{position:relative;width:44px;height:44px}.d-badge-demo-button{display:grid;place-items:center;width:44px;height:44px;padding:0;border:1px solid #ffffff0f;border-radius:12px;background:#202020;box-shadow:0 1px 2px #0000001f,0 8px 20px #0000002e;cursor:pointer;transition:transform var(--dur-fast) var(--ease-pop)}.d-badge-demo-button img{display:block}
.d-badge-demo-count{position:absolute;left:32px;top:-8px;display:grid;place-items:center;min-width:22px;height:18px;padding:0 4px;border-radius:9px;background:#f26d6d;color:white;font:600 11px/14px Inter,system-ui,sans-serif;letter-spacing:.0528px;font-variant-numeric:tabular-nums;pointer-events:none}.d-badge-demo-track{display:flex;white-space:nowrap}.d-badge-demo-digit{display:inline-grid;position:relative}.d-badge-demo-old,.d-badge-demo-new{grid-area:1/1}.d-badge-demo-old{animation:d-badge-demo-out var(--dur-fast) var(--ease-out) both}.d-badge-demo-new{animation:d-badge-demo-in var(--dur-fast) var(--ease-out) both}
.d-badge-demo[data-popping="true"] .d-badge-demo-count{animation:d-badge-demo-travel 260ms var(--ease-out) both,d-badge-demo-scale var(--dur-xslow) var(--ease-pop) both,d-badge-demo-opacity var(--dur-slow) var(--ease-out) both}.d-badge-demo-button:active{transform:scale(.97);transition-duration:var(--dur-micro);transition-timing-function:var(--ease-out)}.d-badge-demo-button:focus-visible{outline:2px solid var(--focus-ring);outline-offset:4px}
.d-badge-demo-status{position:absolute;left:50%;top:50%;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap;font-size:13px}
@keyframes d-badge-demo-travel{from{translate:-8px 12px}to{translate:0 0}}@keyframes d-badge-demo-scale{from{scale:.7}to{scale:1}}@keyframes d-badge-demo-opacity{from{opacity:0}to{opacity:1}}@keyframes d-badge-demo-out{to{opacity:0;transform:translateY(-4px);filter:blur(var(--blur-small))}}@keyframes d-badge-demo-in{from{opacity:0;transform:translateY(4px);filter:blur(var(--blur-small))}to{opacity:1;transform:none;filter:none}}
@media(prefers-reduced-motion:reduce){.d-badge-demo .d-badge-demo-count,.d-badge-demo .d-badge-demo-old,.d-badge-demo .d-badge-demo-new{animation:none}.d-badge-demo-button{transition:opacity var(--dur-quick) var(--ease-out)}.d-badge-demo-button:active{transform:none;opacity:.8}}

.d-micro-btn-polish-stages{position:relative;font-family:Inter,system-ui,sans-serif}.d-micro-btn-polish-stages-rail{position:absolute;left:0;top:-2px;width:270px;height:32px;border:1px solid #ffffff0f;border-radius:9px;background:#171717}.d-micro-btn-polish-stages-indicator{position:absolute;left:2px;top:2px;width:66px;height:26px;border-radius:7px;background:#272727;box-shadow:inset 0 1px #ffffff0f,0 1px 2px #0000001f,0 8px 20px -8px #0000002e;transform:translateX(var(--polish-position,0px));transition:transform var(--dur-fast) var(--ease-out)}
.d-micro-btn-polish-stages-choice{position:absolute;left:2px;top:2px;width:66px;height:26px;padding:0;border:0;border-radius:7px;background:transparent;color:#6a6a6a;font:500 12.5px/16px Inter,system-ui,sans-serif;letter-spacing:-.0175px;cursor:pointer;transition:color var(--dur-fast) var(--ease-out)}.d-micro-btn-polish-stages-choice:nth-of-type(2){left:68px}.d-micro-btn-polish-stages-choice:nth-of-type(3){left:134px}.d-micro-btn-polish-stages-choice:nth-of-type(4){left:200px}.d-micro-btn-polish-stages-choice span{position:absolute;left:18px;top:5px}.d-micro-btn-polish-stages-choice:nth-of-type(2) span{left:11px}.d-micro-btn-polish-stages-choice:nth-of-type(3) span,.d-micro-btn-polish-stages-choice:nth-of-type(4) span{left:14.5px}.d-micro-btn-polish-stages-choice[aria-checked="true"]{color:#f1f1f1}
.d-micro-btn-polish-stages-button{position:absolute;left:70px;top:58px;width:130px;height:42px;padding:0;border:0;border-radius:0;background:#fa7319;color:#111;font:500 13px/16px Inter,system-ui,sans-serif;letter-spacing:-.0416px;cursor:pointer;transition:border-radius var(--dur-quick) var(--ease-out),box-shadow var(--dur-quick) var(--ease-out),translate var(--dur-fast) var(--ease-out),scale var(--dur-fast) var(--ease-pop)}.d-micro-btn-polish-stages-button span{position:absolute;left:14px;top:13px}.d-micro-btn-polish-stages-button img{position:absolute;left:100px;top:13px;display:block}
.d-micro-btn-polish-stages[data-layer="1"] .d-micro-btn-polish-stages-button{border-radius:10px;box-shadow:inset 0 0 0 1px #11111120}.d-micro-btn-polish-stages[data-layer="2"] .d-micro-btn-polish-stages-button{border-radius:10px;box-shadow:inset 0 0 0 1px #11111120,inset 0 1px #ffffff40}.d-micro-btn-polish-stages[data-layer="3"] .d-micro-btn-polish-stages-button{border-radius:10px;box-shadow:inset 0 0 0 1px #11111120,inset 0 1px #ffffff40,0 1px 2px #0000001f,0 8px 20px #0000002e}
.d-micro-btn-polish-stages-button:active,.d-micro-btn-polish-stages[data-auto-press="true"] .d-micro-btn-polish-stages-button{scale:.97;transition:translate var(--dur-quick) var(--ease-out),scale var(--dur-micro) var(--ease-out)}.d-micro-btn-polish-stages-button:focus-visible,.d-micro-btn-polish-stages-choice:focus-visible{outline:2px solid var(--focus-ring);outline-offset:3px}
@media(hover:hover){.d-micro-btn-polish-stages[data-layer="3"] .d-micro-btn-polish-stages-button:hover,.d-micro-btn-polish-stages[data-auto-hover="true"] .d-micro-btn-polish-stages-button{translate:0 -2px;transition:translate var(--dur-quick) var(--ease-out),scale var(--dur-fast) var(--ease-pop)}.d-micro-btn-polish-stages[data-layer="3"] .d-micro-btn-polish-stages-button:active,.d-micro-btn-polish-stages[data-auto-press="true"] .d-micro-btn-polish-stages-button{scale:.97;transition:translate var(--dur-quick) var(--ease-out),scale var(--dur-micro) var(--ease-out)}}
.d-micro-btn-polish-stages-status{position:absolute;left:50%;top:50%;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap;font-size:13px}.d-micro-btn-polish-stages[data-initializing="true"] *{transition:none!important}
@media(prefers-reduced-motion:reduce){.d-micro-btn-polish-stages .d-micro-btn-polish-stages-button{transform:none;translate:0 0;scale:1;transition:opacity var(--dur-quick) var(--ease-out)}.d-micro-btn-polish-stages .d-micro-btn-polish-stages-button:active{opacity:.8}.d-micro-btn-polish-stages-indicator{transition:none}.d-micro-btn-polish-stages-choice{transition:color var(--dur-quick) var(--ease-out)}}
